def least_interval(tasks, n):
    counts = {}
    for t in tasks:
        counts[t] = counts.get(t, 0) + 1
    hi = max(counts.values())
    ties = sum(1 for v in counts.values() if v == hi)
    return max(len(tasks), (hi - 1) * (n + 1) + ties)
